module.exports = {"version":1,"category":"政治理论","title":"国考政治理论题库","questionCount":60,"materials":[],"questions":[{"id":"politics-001","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"习近平新时代中国特色社会主义思想明确，中国特色社会主义最本质的特征是：","materialId":null,"options":[{"key":"A","text":"人民当家作主"},{"key":"B","text":"社会主义市场经济"},{"key":"C","text":"中国共产党领导"},{"key":"D","text":"依法治国"}],"answer":"C","explanation":"中国共产党领导是中国特色社会主义最本质的特征，也是中国特色社会主义制度的最大优势。人民当家作主、依法治国和社会主义市场经济都具有重要地位，但不对应题干所问的这一特定论断。","knowledgePoints":["中国特色社会主义最本质特征","党的领导"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-002","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"新时代坚持和发展中国特色社会主义的根本立场是：","materialId":null,"options":[{"key":"A","text":"坚持守正创新"},{"key":"B","text":"坚持胸怀天下"},{"key":"C","text":"坚持系统观念"},{"key":"D","text":"坚持人民至上"}],"answer":"D","explanation":"人民立场是中国共产党的根本政治立场，坚持人民至上体现了新时代坚持和发展中国特色社会主义的根本立场。其余三项属于重要世界观和方法论要求，但不直接回答“根本立场”。","knowledgePoints":["人民至上","根本政治立场"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-003","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"党的二十大报告指出，中国共产党的中心任务是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，并以何种方式全面推进中华民族伟大复兴？","materialId":null,"options":[{"key":"A","text":"共同富裕"},{"key":"B","text":"高质量发展"},{"key":"C","text":"中国式现代化"},{"key":"D","text":"全过程人民民主"}],"answer":"C","explanation":"党的二十大报告将新时代新征程党的中心任务概括为全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。","knowledgePoints":["党的中心任务","中国式现代化"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-004","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"中国式现代化是人口规模巨大的现代化、全体人民共同富裕的现代化、物质文明和精神文明相协调的现代化、人与自然和谐共生的现代化，以及：","materialId":null,"options":[{"key":"A","text":"走和平发展道路的现代化"},{"key":"B","text":"优先发展重工业的现代化"},{"key":"C","text":"同步实现各地区富裕的现代化"},{"key":"D","text":"以资本扩张为中心的现代化"}],"answer":"A","explanation":"走和平发展道路的现代化是中国式现代化五个中国特色之一。中国式现代化不以资本为中心，也不要求地区之间在同一时点、以同一步骤实现富裕。","knowledgePoints":["中国式现代化的中国特色"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-005","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"全面建设社会主义现代化国家的首要任务是：","materialId":null,"options":[{"key":"A","text":"扩大经济总量"},{"key":"B","text":"发展外向型经济"},{"key":"C","text":"高质量发展"},{"key":"D","text":"提高城镇化率"}],"answer":"C","explanation":"党的二十大报告明确，高质量发展是全面建设社会主义现代化国家的首要任务。经济总量、城镇化和对外经济都应服务于高质量发展，而不能替代这一总体要求。","knowledgePoints":["高质量发展","首要任务"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-006","category":"政治理论","subtype":"党的创新理论","difficulty":"easy","stem":"全面建成社会主义现代化强国的战略安排分两步走。到2035年，我国发展的总体目标之一是：","materialId":null,"options":[{"key":"A","text":"基本实现社会主义现代化"},{"key":"B","text":"建成世界第一经济强国"},{"key":"C","text":"实现全体人民收入完全相同"},{"key":"D","text":"全面取消城乡差别"}],"answer":"A","explanation":"两步走战略安排的第一步是从2020年到2035年基本实现社会主义现代化，第二步是到本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国。其他选项均非规范目标。","knowledgePoints":["两步走战略安排","2035年目标"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-007","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"某地制定现代化建设方案，提出“先污染后治理，以资源高消耗换取短期增长”。这一思路最直接违背中国式现代化的哪一特征？","materialId":null,"options":[{"key":"A","text":"人口规模巨大"},{"key":"B","text":"全体人民共同富裕"},{"key":"C","text":"物质文明和精神文明相协调"},{"key":"D","text":"人与自然和谐共生"}],"answer":"D","explanation":"以高消耗和污染换增长割裂了发展与生态保护的关系，直接违背人与自然和谐共生的现代化要求。题干没有直接涉及人口规模、收入分配或物质文明与精神文明的协调。","knowledgePoints":["中国式现代化","人与自然和谐共生"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-008","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"关于“两个结合”，下列理解正确的是：","materialId":null,"options":[{"key":"A","text":"把国外现代化模式同中国国情简单叠加"},{"key":"B","text":"把市场机制同计划手段完全分离"},{"key":"C","text":"把传统文化全部直接用于国家治理"},{"key":"D","text":"把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合"}],"answer":"D","explanation":"“两个结合”是把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。它强调创造性结合，既不是照搬传统，也不是移植国外模式。","knowledgePoints":["两个结合","马克思主义中国化时代化"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-009","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"“必须坚持问题导向”要求理论创新着眼于：","materialId":null,"options":[{"key":"A","text":"回避发展中的矛盾"},{"key":"B","text":"回答中国之问、世界之问、人民之问、时代之问"},{"key":"C","text":"只研究抽象概念体系"},{"key":"D","text":"以既有结论代替实践探索"}],"answer":"B","explanation":"坚持问题导向，就是聚焦实践遇到的新问题、改革发展稳定的深层次问题等，不断提出解决问题的新理念新思路新办法，回答中国之问、世界之问、人民之问、时代之问。","knowledgePoints":["问题导向","六个必须坚持"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-010","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"推进中国式现代化必须牢牢把握的重大原则，不包括：","materialId":null,"options":[{"key":"A","text":"坚持和加强党的全面领导"},{"key":"B","text":"坚持中国特色社会主义道路"},{"key":"C","text":"坚持以封闭方式配置资源"},{"key":"D","text":"坚持深化改革开放"}],"answer":"C","explanation":"推进中国式现代化要坚持和加强党的全面领导、坚持中国特色社会主义道路、坚持以人民为中心的发展思想、坚持深化改革开放、坚持发扬斗争精神。封闭配置资源与深化改革开放相悖。","knowledgePoints":["中国式现代化重大原则"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-011","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"新质生产力的显著特点是创新，关键在质优，本质是：","materialId":null,"options":[{"key":"A","text":"提高行政配置比重"},{"key":"B","text":"扩大传统产能"},{"key":"C","text":"增加要素投入"},{"key":"D","text":"先进生产力"}],"answer":"D","explanation":"新质生产力由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象优化组合的跃升为基本内涵，本质是先进生产力。","knowledgePoints":["新质生产力","高质量发展"],"sourceRefs":[{"kind":"official","title":"习近平在中共中央政治局第十一次集体学习时强调 加快发展新质生产力 扎实推进高质量发展","url":"https://www.mee.gov.cn/ywdt/szyw/202402/t20240201_1065496.shtml","publishedAt":"2024-02-01","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-012","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"发展新质生产力不是忽视、放弃传统产业。对此理解最准确的是：","materialId":null,"options":[{"key":"A","text":"所有传统产业都应保持原有技术路线"},{"key":"B","text":"传统产业只能退出市场"},{"key":"C","text":"应通过技术改造和转型升级焕发传统产业新活力"},{"key":"D","text":"新兴产业与传统产业不能同时发展"}],"answer":"C","explanation":"因地制宜发展新质生产力，既要培育新兴产业和未来产业，也要用新技术改造提升传统产业，不能把“新质”简单等同于只发展新兴产业。","knowledgePoints":["新质生产力","传统产业转型升级"],"sourceRefs":[{"kind":"official","title":"习近平在中共中央政治局第十一次集体学习时强调 加快发展新质生产力 扎实推进高质量发展","url":"https://www.mee.gov.cn/ywdt/szyw/202402/t20240201_1065496.shtml","publishedAt":"2024-02-01","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-013","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"全过程人民民主的本质属性和核心要义是：","materialId":null,"options":[{"key":"A","text":"民主程序固定不变"},{"key":"B","text":"只在基层实行民主"},{"key":"C","text":"人民当家作主"},{"key":"D","text":"以协商取代选举"}],"answer":"C","explanation":"人民当家作主是社会主义民主政治的本质和核心。全过程人民民主把选举民主与协商民主等形式贯通起来，覆盖国家政治生活和社会生活各环节，并非局限于基层或单一形式。","knowledgePoints":["全过程人民民主","人民当家作主"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-014","category":"政治理论","subtype":"党的创新理论","difficulty":"medium","stem":"中国共产党为什么能，中国特色社会主义为什么好，归根到底是：","materialId":null,"options":[{"key":"A","text":"行政手段能够替代市场机制"},{"key":"B","text":"自然资源丰富"},{"key":"C","text":"单一发展模式长期不变"},{"key":"D","text":"马克思主义行，是中国化时代化的马克思主义行"}],"answer":"D","explanation":"党的二十大报告指出，归根到底是马克思主义行，是中国化时代化的马克思主义行。这揭示了党的事业和中国特色社会主义事业取得成功的思想理论根源。","knowledgePoints":["马克思主义中国化时代化"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-015","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"某市改革中既坚持公有制主体地位和共同富裕方向，又根据数字经济发展完善数据要素配置规则。这最能体现哪一思想方法？","materialId":null,"options":[{"key":"A","text":"坚持守正创新"},{"key":"B","text":"坚持自信自立"},{"key":"C","text":"坚持胸怀天下"},{"key":"D","text":"坚持问题导向"}],"answer":"A","explanation":"坚持社会主义基本制度和共同富裕方向属于“守正”，面向数字经济创造新的要素配置规则属于“创新”。两者统一，最直接体现坚持守正创新。","knowledgePoints":["六个必须坚持","守正创新"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-016","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"下列做法中，最符合“坚持系统观念”的是：","materialId":null,"options":[{"key":"A","text":"只考核单项经济增速，不考虑民生和生态"},{"key":"B","text":"把改革政策按部门分别推进，避免部门协调"},{"key":"C","text":"统筹发展和安全、效率和公平、活力和秩序"},{"key":"D","text":"遇到复杂问题时仅沿用过去经验"}],"answer":"C","explanation":"系统观念要求从事物相互联系、相互作用出发，加强前瞻性思考、全局性谋划、整体性推进，统筹处理发展和安全、效率和公平等重大关系。其余做法均片面割裂。","knowledgePoints":["系统观念","重大关系统筹"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-017","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"关于共同富裕，下列说法最准确的是：","materialId":null,"options":[{"key":"A","text":"共同富裕等于所有人同一时间达到相同收入"},{"key":"B","text":"共同富裕只涉及物质生活，不涉及精神生活"},{"key":"C","text":"共同富裕是全体人民的富裕，需要在高质量发展中促进"},{"key":"D","text":"共同富裕要求取消一切合理收入差距"}],"answer":"C","explanation":"共同富裕是全体人民共同富裕，是人民群众物质生活和精神生活都富裕，不是整齐划一的平均主义，也不是同时同步同等富裕，应在高质量发展中促进。","knowledgePoints":["共同富裕","高质量发展"],"sourceRefs":[{"kind":"official","title":"扎实推动共同富裕","url":"https://www.cac.gov.cn/2021-10/15/c_1635892097526965.htm","publishedAt":"2021-10-15","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-018","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"“江山就是人民，人民就是江山”主要揭示了：","materialId":null,"options":[{"key":"A","text":"政权建设与人民立场的内在统一"},{"key":"B","text":"国家权力来源于经济增长速度"},{"key":"C","text":"人民利益与党的利益可以分离"},{"key":"D","text":"国家治理只需满足多数人的短期偏好"}],"answer":"A","explanation":"这一论断强调打江山、守江山守的是人民的心，反映党的性质宗旨和人民立场，揭示党长期执政根基在人民。它不把执政基础归结为单一经济指标或短期偏好。","knowledgePoints":["人民立场","党的执政根基"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-019","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"下列对中国式现代化与人类文明新形态关系的理解，正确的是：","materialId":null,"options":[{"key":"A","text":"中国式现代化否定现代化的一切共同特征"},{"key":"B","text":"中国式现代化只能适用于中国，因而没有世界意义"},{"key":"C","text":"中国式现代化既有各国现代化共同特征，更有基于国情的中国特色"},{"key":"D","text":"中国式现代化要求其他国家照搬中国方案"}],"answer":"C","explanation":"中国式现代化既遵循现代化的一般规律，又立足中国具体国情，创造了人类文明新形态，为人类实现现代化提供新的选择，但不要求其他国家照搬。","knowledgePoints":["中国式现代化","人类文明新形态"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-020","category":"政治理论","subtype":"党的创新理论","difficulty":"hard","stem":"面对改革中的深层次利益调整，既要增强改革的系统性、整体性、协同性，又要鼓励基层在法治轨道内探索。该要求体现的辩证关系是：","materialId":null,"options":[{"key":"A","text":"顶层设计与实践探索相统一"},{"key":"B","text":"政府与市场彼此替代"},{"key":"C","text":"局部利益高于整体利益"},{"key":"D","text":"改革速度与改革方向无关"}],"answer":"A","explanation":"系统性整体性协同性需要加强顶层设计，基层依法探索则发挥实践首创精神。二者相互促进，体现顶层设计与实践探索相统一，而不是政府市场相互替代或局部凌驾整体。","knowledgePoints":["全面深化改革","顶层设计与基层探索"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-021","category":"政治理论","subtype":"党和国家方针政策","difficulty":"easy","stem":"进一步全面深化改革的总目标是继续完善和发展中国特色社会主义制度，推进：","materialId":null,"options":[{"key":"A","text":"行政审批事项持续增加"},{"key":"B","text":"所有公共服务市场化"},{"key":"C","text":"区域发展模式完全一致"},{"key":"D","text":"国家治理体系和治理能力现代化"}],"answer":"D","explanation":"党的二十届三中全会《决定》明确，进一步全面深化改革的总目标是继续完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化。","knowledgePoints":["进一步全面深化改革总目标"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-022","category":"政治理论","subtype":"党和国家方针政策","difficulty":"easy","stem":"在社会主义市场经济体制中，市场在资源配置中起什么作用？","materialId":null,"options":[{"key":"A","text":"基础性作用"},{"key":"B","text":"唯一作用"},{"key":"C","text":"决定性作用"},{"key":"D","text":"补充性作用"}],"answer":"C","explanation":"我国经济体制改革的核心问题是处理好政府和市场关系，使市场在资源配置中起决定性作用，更好发挥政府作用。“决定性”不等于市场是唯一机制。","knowledgePoints":["社会主义市场经济","政府和市场关系"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-023","category":"政治理论","subtype":"党和国家方针政策","difficulty":"easy","stem":"建设全国统一大市场，基础制度之一是：","materialId":null,"options":[{"key":"A","text":"统一的市场准入制度"},{"key":"B","text":"各地自行设置企业迁移壁垒"},{"key":"C","text":"按行政区划分割商品市场"},{"key":"D","text":"限制要素跨区域流动"}],"answer":"A","explanation":"全国统一大市场要求强化市场基础制度规则统一，包括统一产权保护、市场准入、公平竞争、社会信用等制度。地方保护和市场分割与统一大市场方向相反。","knowledgePoints":["全国统一大市场","市场准入"],"sourceRefs":[{"kind":"official","title":"中共中央 国务院关于加快建设全国统一大市场的意见","url":"https://www.gov.cn/zhengce/2022-04/10/content_5684385.htm","publishedAt":"2022-04-10","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-024","category":"政治理论","subtype":"党和国家方针政策","difficulty":"easy","stem":"乡村振兴的总要求是产业兴旺、生态宜居、乡风文明、治理有效和：","materialId":null,"options":[{"key":"A","text":"产业单一化"},{"key":"B","text":"同步城市化"},{"key":"C","text":"耕地非农化"},{"key":"D","text":"生活富裕"}],"answer":"D","explanation":"产业兴旺、生态宜居、乡风文明、治理有效、生活富裕构成实施乡村振兴战略的总要求，五个方面相互联系，不能以单一产业或非农化替代。","knowledgePoints":["乡村振兴战略总要求"],"sourceRefs":[{"kind":"official","title":"中共中央 国务院关于实施乡村振兴战略的意见","url":"https://www.gov.cn/zhengce/2018-02/04/content_5263807.htm","publishedAt":"2018-02-04","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-025","category":"政治理论","subtype":"党和国家方针政策","difficulty":"easy","stem":"保障国家粮食安全，必须落实最严格的耕地保护制度，牢牢守住：","materialId":null,"options":[{"key":"A","text":"生态保护红线"},{"key":"B","text":"耕地红线"},{"key":"C","text":"城市开发边界"},{"key":"D","text":"能源消费上限"}],"answer":"B","explanation":"耕地是粮食生产的命根子，保障粮食安全必须落实最严格的耕地保护制度，严守耕地红线，稳定粮食播种面积和产能。其他边界服务于不同治理目标。","knowledgePoints":["粮食安全","耕地保护"],"sourceRefs":[{"kind":"official","title":"中华人民共和国粮食安全保障法","url":"https://www.gov.cn/yaowen/liebiao/202312/content_6923387.htm","publishedAt":"2023-12-29","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-026","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"某地拟以“支持本地企业”为由，要求外地企业进入当地公共资源交易市场前额外设立分公司。该做法主要违背：","materialId":null,"options":[{"key":"A","text":"全国统一大市场和公平竞争要求"},{"key":"B","text":"按劳分配原则"},{"key":"C","text":"居民消费自由"},{"key":"D","text":"宏观调控逆周期要求"}],"answer":"A","explanation":"对外地企业附加本地设立机构条件，构成地方保护和市场分割，妨碍经营主体平等准入，违背建设全国统一大市场和公平竞争原则。","knowledgePoints":["全国统一大市场","公平竞争"],"sourceRefs":[{"kind":"official","title":"中共中央 国务院关于加快建设全国统一大市场的意见","url":"https://www.gov.cn/zhengce/2022-04/10/content_5684385.htm","publishedAt":"2022-04-10","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-027","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"健全宏观经济治理体系，应加强财政政策和货币政策的协调配合，其主要目的在于：","materialId":null,"options":[{"key":"A","text":"取消市场价格机制"},{"key":"B","text":"提高宏观调控的前瞻性、针对性和有效性"},{"key":"C","text":"使所有行业保持相同利润率"},{"key":"D","text":"由政府决定每项商品产量"}],"answer":"B","explanation":"财政、货币等宏观政策协调，有助于形成政策合力，增强宏观政策取向一致性，提高调控的前瞻性、针对性和有效性，而不是替代市场微观决策。","knowledgePoints":["宏观经济治理","政策协调"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-028","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"深化科技体制改革，强化企业科技创新主体地位，意味着：","materialId":null,"options":[{"key":"A","text":"基础研究全部交由企业承担"},{"key":"B","text":"推动创新链产业链资金链人才链深度融合"},{"key":"C","text":"政府退出科技创新政策支持"},{"key":"D","text":"以企业短期利润作为科研唯一标准"}],"answer":"B","explanation":"强化企业创新主体地位重在促进科技创新与产业创新深度融合，推动创新链产业链资金链人才链贯通。基础研究、政府支持和长期价值仍不可缺少。","knowledgePoints":["科技体制改革","企业创新主体"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-029","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"完善高水平对外开放体制机制，应当：","materialId":null,"options":[{"key":"A","text":"以国内国际市场相互隔离为目标"},{"key":"B","text":"仅扩大商品出口数量"},{"key":"C","text":"取消所有外资监管"},{"key":"D","text":"稳步扩大制度型开放"}],"answer":"D","explanation":"高水平对外开放不仅是商品和要素流动型开放，还包括规则、规制、管理、标准等制度型开放。开放不等于取消必要监管，也不意味着割裂国内国际市场。","knowledgePoints":["高水平对外开放","制度型开放"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-030","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"推动区域协调发展，下列举措最符合因地制宜、优势互补要求的是：","materialId":null,"options":[{"key":"A","text":"要求所有地区建立相同产业体系"},{"key":"B","text":"根据主体功能定位发挥各地区比较优势"},{"key":"C","text":"限制劳动力和资本跨地区流动"},{"key":"D","text":"以行政区划阻断产业协作"}],"answer":"B","explanation":"区域协调发展不是追求产业同构，而是按照主体功能定位和资源禀赋发挥比较优势，促进要素合理流动和区域协作，形成优势互补的区域经济布局。","knowledgePoints":["区域协调发展","主体功能区"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-031","category":"政治理论","subtype":"党和国家方针政策","difficulty":"hard","stem":"处理好有效市场和有为政府关系，下列做法最恰当的是：","materialId":null,"options":[{"key":"A","text":"凡市场能配置的资源，政府均不得监管"},{"key":"B","text":"政府直接替代企业作出投资经营决策"},{"key":"C","text":"充分发挥市场决定性作用，同时依法弥补市场失灵、维护公平秩序"},{"key":"D","text":"把政府审批数量作为治理能力的主要指标"}],"answer":"C","explanation":"有效市场与有为政府不是二选一。市场有效配置资源，政府通过宏观调控、公共服务、市场监管等依法弥补市场失灵，共同形成既“放得活”又“管得住”的经济秩序。","knowledgePoints":["有效市场","有为政府"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-032","category":"政治理论","subtype":"党和国家方针政策","difficulty":"hard","stem":"在推进改革中强调“先立后破、不立不破”，其政策含义主要是：","materialId":null,"options":[{"key":"A","text":"拒绝改变任何旧制度"},{"key":"B","text":"新机制形成并具备承接能力后，再有序调整旧机制"},{"key":"C","text":"先取消旧规则，再讨论替代安排"},{"key":"D","text":"改革只能局限于增量领域"}],"answer":"B","explanation":"“先立后破、不立不破”强调把握改革时序和节奏，先建立可行的新制度新机制，再稳妥有序破除不适应发展的旧机制，防止出现制度真空和风险外溢。","knowledgePoints":["改革方法论","先立后破"],"sourceRefs":[{"kind":"official","title":"中央经济工作会议在北京举行","url":"https://www.gov.cn/yaowen/liebiao/202312/content_6919834.htm","publishedAt":"2023-12-12","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-033","category":"政治理论","subtype":"党和国家方针政策","difficulty":"hard","stem":"某项产业政策出台前分别评估其对就业、物价、生态和经营主体预期的影响，这主要落实了：","materialId":null,"options":[{"key":"A","text":"行业自我监管替代政府监管"},{"key":"B","text":"地方保护制度"},{"key":"C","text":"单一目标决策机制"},{"key":"D","text":"宏观政策取向一致性评估"}],"answer":"D","explanation":"将非经济性政策纳入宏观政策取向一致性评估，关注政策对经济社会多方面的综合影响，有助于形成政策合力、稳定预期，避免政策目标相互冲突。","knowledgePoints":["宏观政策取向一致性","政策评估"],"sourceRefs":[{"kind":"official","title":"中央经济工作会议在北京举行","url":"https://www.gov.cn/yaowen/liebiao/202312/content_6919834.htm","publishedAt":"2023-12-12","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-034","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"完善促进机会公平的制度机制，最直接的政策着力点是：","materialId":null,"options":[{"key":"A","text":"以身份限制公共就业服务"},{"key":"B","text":"健全就业公共服务体系，破除妨碍劳动力流动的制度障碍"},{"key":"C","text":"由政府统一确定个人职业"},{"key":"D","text":"只提高少数行业准入门槛"}],"answer":"B","explanation":"机会公平强调在教育、就业、社会流动等方面提供公平可及的制度条件。健全公共就业服务并破除不合理流动障碍，可直接扩大平等参与和发展机会。","knowledgePoints":["机会公平","就业公共服务"],"sourceRefs":[{"kind":"official","title":"中共中央关于进一步全面深化改革、推进中国式现代化的决定","url":"https://www.gov.cn/zhengce/202407/content_6963770.htm","publishedAt":"2024-07-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-035","category":"政治理论","subtype":"党和国家方针政策","difficulty":"medium","stem":"统筹高质量发展和高水平安全，正确的理解是：","materialId":null,"options":[{"key":"A","text":"安全会阻碍发展，因此应暂缓安全治理"},{"key":"B","text":"高水平安全要求停止开放合作"},{"key":"C","text":"发展是安全的基础，安全是发展的条件，二者应动态平衡、相互促进"},{"key":"D","text":"只要经济增长即可自然消除所有风险"}],"answer":"C","explanation":"发展和安全相辅相成。高质量发展为安全提供物质技术基础，高水平安全为发展营造稳定环境，应同步谋划推进，而非以一方排斥另一方。","knowledgePoints":["统筹发展和安全","总体国家安全观"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-036","category":"政治理论","subtype":"法治与国家治理","difficulty":"easy","stem":"全面依法治国的根本遵循和行动指南是：","materialId":null,"options":[{"key":"A","text":"行业自治规则"},{"key":"B","text":"部门规章汇编"},{"key":"C","text":"地方治理惯例"},{"key":"D","text":"习近平法治思想"}],"answer":"D","explanation":"习近平法治思想深刻回答新时代为什么实行全面依法治国、怎样实行全面依法治国等重大理论和实践问题，是全面依法治国的根本遵循和行动指南。","knowledgePoints":["习近平法治思想","全面依法治国"],"sourceRefs":[{"kind":"official","title":"中央全面依法治国工作会议召开","url":"https://www.gov.cn/xinwen/2020-11/17/content_5562085.htm","publishedAt":"2020-11-17","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-037","category":"政治理论","subtype":"法治与国家治理","difficulty":"easy","stem":"我国宪法规定，中华人民共和国的一切权力属于：","materialId":null,"options":[{"key":"A","text":"国家机关工作人员"},{"key":"B","text":"国务院"},{"key":"C","text":"全国人民代表大会"},{"key":"D","text":"人民"}],"answer":"D","explanation":"宪法第二条规定，中华人民共和国的一切权力属于人民。人民通过全国人民代表大会和地方各级人民代表大会行使国家权力，人大是权力行使机关，不是权力最终归属者。","knowledgePoints":["宪法","国家权力归属"],"sourceRefs":[{"kind":"official","title":"中华人民共和国宪法","url":"https://www.gov.cn/guoqing/2018-03/22/content_5276318.htm","publishedAt":"2018-03-22","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-038","category":"政治理论","subtype":"法治与国家治理","difficulty":"easy","stem":"依法行政的基本要求之一是行政机关行使职权必须：","materialId":null,"options":[{"key":"A","text":"于法有据、程序正当"},{"key":"B","text":"以内部口头通知代替法定程序"},{"key":"C","text":"优先考虑部门利益"},{"key":"D","text":"不受司法监督"}],"answer":"A","explanation":"依法行政要求行政权在法治轨道内运行，做到职权法定、程序正当、权责统一并接受监督。内部通知、部门利益优先和排斥监督都不符合依法行政。","knowledgePoints":["依法行政","法治政府"],"sourceRefs":[{"kind":"official","title":"法治政府建设实施纲要（2021－2025年）","url":"https://www.gov.cn/zhengce/2021-08/11/content_5630802.htm","publishedAt":"2021-08-11","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-039","category":"政治理论","subtype":"法治与国家治理","difficulty":"medium","stem":"行政机关实施行政处罚时，应当告知当事人事实、理由、依据以及依法享有的权利。这主要体现：","materialId":null,"options":[{"key":"A","text":"行政秘密原则"},{"key":"B","text":"效率优先原则"},{"key":"C","text":"权力无限原则"},{"key":"D","text":"程序正当原则"}],"answer":"D","explanation":"事先告知并保障陈述、申辩等权利，是行政处罚法定程序的重要内容，体现程序正当和权利保障。行政效率不能成为省略法定程序的理由。","knowledgePoints":["行政处罚","程序正当"],"sourceRefs":[{"kind":"official","title":"中华人民共和国行政处罚法","url":"https://gdb.beijing.gov.cn/rf_zwgk/2024zcwj/2024_flfg/202406/t20240603_3701571.html","publishedAt":"2021-01-23","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-040","category":"政治理论","subtype":"法治与国家治理","difficulty":"medium","stem":"关于依法治国和依规治党的关系，下列说法正确的是：","materialId":null,"options":[{"key":"A","text":"党内法规可以替代国家法律"},{"key":"B","text":"二者彼此独立，无需衔接"},{"key":"C","text":"坚持依法治国和依规治党有机统一"},{"key":"D","text":"国家法律不适用于党员干部"}],"answer":"C","explanation":"全面依法治国要求依法治国与依规治党有机统一，党内法规与国家法律各有调整范围并应协调衔接。党员干部既受国家法律约束，也受党内法规约束。","knowledgePoints":["依法治国","依规治党"],"sourceRefs":[{"kind":"official","title":"中央全面依法治国工作会议召开","url":"https://www.gov.cn/xinwen/2020-11/17/content_5562085.htm","publishedAt":"2020-11-17","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-041","category":"政治理论","subtype":"法治与国家治理","difficulty":"medium","stem":"某机关拟将本部门没有法定依据的检查事项纳入常态化检查清单。对此评价正确的是：","materialId":null,"options":[{"key":"A","text":"只要有利于管理即可实施"},{"key":"B","text":"违反职权法定要求，不得擅自创设检查权"},{"key":"C","text":"经部门负责人同意即可实施"},{"key":"D","text":"检查不属于行政权，无需法律依据"}],"answer":"B","explanation":"行政机关职权来源于法律法规授权，法无授权不可为。没有法定依据，不得以内部清单或负责人同意擅自创设检查事项，否则会不当增加经营主体负担。","knowledgePoints":["职权法定","规范涉企检查"],"sourceRefs":[{"kind":"official","title":"法治政府建设实施纲要（2021－2025年）","url":"https://www.gov.cn/zhengce/2021-08/11/content_5630802.htm","publishedAt":"2021-08-11","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-042","category":"政治理论","subtype":"法治与国家治理","difficulty":"medium","stem":"民法典被称为“社会生活的百科全书”，其编纂体现的国家治理价值主要是：","materialId":null,"options":[{"key":"A","text":"以系统完备的民事规则保障民事主体合法权益"},{"key":"B","text":"用民法调整所有刑事犯罪"},{"key":"C","text":"取消行政管理法律制度"},{"key":"D","text":"以行业惯例排除法律适用"}],"answer":"A","explanation":"民法典系统整合物权、合同、人格权、婚姻家庭、继承、侵权责任等民事制度，为民事活动提供基本遵循并保障民事权利。它不调整所有刑事或行政关系。","knowledgePoints":["民法典","民事权利保障"],"sourceRefs":[{"kind":"official","title":"中华人民共和国民法典","publishedAt":"2020-06-01","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-043","category":"政治理论","subtype":"法治与国家治理","difficulty":"hard","stem":"关于重大行政决策，下列流程最符合科学、民主、依法决策要求的是：","materialId":null,"options":[{"key":"A","text":"先作决定，再补做风险评估和合法性审查"},{"key":"B","text":"公众参与、专家论证、风险评估、合法性审查和集体讨论决定依法有序衔接"},{"key":"C","text":"由承办人员个人决定，减少程序成本"},{"key":"D","text":"只要进行专家论证即可免除其他法定程序"}],"answer":"B","explanation":"重大行政决策应依法履行相应程序。公众参与、专家论证、风险评估、合法性审查和集体讨论决定各有功能，应根据事项依法衔接，不能倒置、替代或事后补做。","knowledgePoints":["重大行政决策程序","依法决策"],"sourceRefs":[{"kind":"official","title":"重大行政决策程序暂行条例","url":"https://www.gov.cn/zhengce/content/2019-05/08/content_5389670.htm","publishedAt":"2019-05-08","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-044","category":"政治理论","subtype":"法治与国家治理","difficulty":"hard","stem":"某行政机关对同类违法行为，在事实、性质、情节相近时作出差异悬殊的处罚，且不能说明理由。该做法主要损害：","materialId":null,"options":[{"key":"A","text":"行政执法的公平公正和裁量基准统一"},{"key":"B","text":"行政机关的组织独立性"},{"key":"C","text":"市场主体的商业秘密"},{"key":"D","text":"立法机关的立法权限"}],"answer":"A","explanation":"同类事项应遵循相对统一的裁量标准，差异处理需有事实和法律上的合理理由。无理由的悬殊处罚会造成同案不同罚，损害公平公正和执法公信力。","knowledgePoints":["行政裁量基准","公平公正执法"],"sourceRefs":[{"kind":"official","title":"国务院办公厅关于进一步规范行政裁量权基准制定和管理工作的意见","publishedAt":"2022-08-17","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-045","category":"政治理论","subtype":"法治与国家治理","difficulty":"medium","stem":"推进基层治理现代化，应当坚持和发展新时代“枫桥经验”，其核心取向是：","materialId":null,"options":[{"key":"A","text":"把所有矛盾上交上级处理"},{"key":"B","text":"依靠群众、依法及时就地化解矛盾纠纷"},{"key":"C","text":"以行政命令代替协商调解"},{"key":"D","text":"取消基层自治组织"}],"answer":"B","explanation":"新时代“枫桥经验”强调坚持党的领导、依靠群众，运用法治方式及时把矛盾纠纷化解在基层、化解在萌芽状态，提升基层治理效能。","knowledgePoints":["枫桥经验","基层治理"],"sourceRefs":[{"kind":"official","title":"坚持和发展新时代“枫桥经验” 提升矛盾纠纷预防化解法治化水平","publishedAt":"2023-11-06","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-046","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"easy","stem":"我国基本经济制度包括公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，以及：","materialId":null,"options":[{"key":"A","text":"国有经济垄断所有行业"},{"key":"B","text":"单一计划经济体制"},{"key":"C","text":"平均分配制度"},{"key":"D","text":"社会主义市场经济体制"}],"answer":"D","explanation":"公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制，共同构成社会主义基本经济制度。","knowledgePoints":["社会主义基本经济制度"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-047","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"easy","stem":"就业是最基本的民生。实施就业优先战略，应当把促进哪一群体就业摆在更加突出的位置？","materialId":null,"options":[{"key":"A","text":"青年特别是高校毕业生"},{"key":"B","text":"仅高收入群体"},{"key":"C","text":"仅机关事业单位人员"},{"key":"D","text":"仅超大城市户籍人口"}],"answer":"A","explanation":"就业政策强调促进高质量充分就业，把高校毕业生等青年就业作为重中之重，同时做好农民工、退役军人、就业困难人员等群体就业工作。","knowledgePoints":["就业优先","重点群体就业"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-048","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"easy","stem":"社会主义核心价值观在国家层面的价值目标是：","materialId":null,"options":[{"key":"A","text":"自由、平等、公正、法治"},{"key":"B","text":"爱国、敬业、诚信、友善"},{"key":"C","text":"富强、民主、文明、和谐"},{"key":"D","text":"创新、协调、绿色、开放"}],"answer":"C","explanation":"富强、民主、文明、和谐是国家层面的价值目标；自由、平等、公正、法治是社会层面的价值取向；爱国、敬业、诚信、友善是公民个人层面的价值准则。","knowledgePoints":["社会主义核心价值观"],"sourceRefs":[{"kind":"official","title":"关于培育和践行社会主义核心价值观的意见","url":"https://www.gov.cn/zhengce/2013-12/23/content_5407875.htm","publishedAt":"2013-12-23","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-049","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"easy","stem":"“绿水青山就是金山银山”理念强调：","materialId":null,"options":[{"key":"A","text":"只要治理污染即可忽视节约资源"},{"key":"B","text":"生态保护必然排斥经济活动"},{"key":"C","text":"生态保护与经济发展可以相互促进"},{"key":"D","text":"经济增长可无限突破资源环境约束"}],"answer":"C","explanation":"“两山”理念揭示保护生态环境就是保护生产力、改善生态环境就是发展生产力，要求推动生态优势转化为发展优势，实现高质量发展与高水平保护协同。","knowledgePoints":["两山理念","生态文明建设"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-050","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"构建初次分配、再分配、第三次分配协调配套的制度体系，下列对应正确的是：","materialId":null,"options":[{"key":"A","text":"社会保障缴费不涉及再分配"},{"key":"B","text":"个人所得税主要属于第三次分配"},{"key":"C","text":"公益慈善主要属于再分配"},{"key":"D","text":"工资报酬主要属于初次分配"}],"answer":"D","explanation":"劳动报酬、生产要素收入等主要在初次分配形成；税收、社会保障和转移支付是再分配的重要手段；公益慈善等社会自愿行为属于第三次分配。","knowledgePoints":["收入分配制度","三次分配"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-051","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"健全多层次社会保障体系，应遵循的原则是：","materialId":null,"options":[{"key":"A","text":"覆盖全民、统筹城乡、公平统一、安全规范、可持续"},{"key":"B","text":"福利水平只能提高，完全不考虑承受能力"},{"key":"C","text":"按户籍永久固化保障权益"},{"key":"D","text":"由商业保险完全替代基本社会保险"}],"answer":"A","explanation":"社会保障体系建设既要提高覆盖面和公平性，也要确保制度规范安全和长期可持续。基本社会保险发挥主体保障作用，商业保险是多层次体系的补充。","knowledgePoints":["社会保障体系","民生建设"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-052","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"推进健康中国建设，下列措施最符合“以人民健康为中心、预防为主”的是：","materialId":null,"options":[{"key":"A","text":"只增加重症治疗资源，不开展健康教育"},{"key":"B","text":"完善疾病预防控制体系，促进医防融合"},{"key":"C","text":"将公共卫生服务完全交由个人承担"},{"key":"D","text":"减少基层医疗卫生服务供给"}],"answer":"B","explanation":"预防为主要求关口前移，健全公共卫生和疾病预防控制体系，推动医疗与预防协同。只重治疗、弱化公共卫生和基层服务不符合健康中国方向。","knowledgePoints":["健康中国","医防融合"],"sourceRefs":[{"kind":"official","title":"“健康中国2030”规划纲要","url":"https://www.gov.cn/zhengce/2016-10/25/content_5124174.htm","publishedAt":"2016-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-053","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"建设教育强国，必须坚持教育的根本任务是：","materialId":null,"options":[{"key":"A","text":"压缩职业教育"},{"key":"B","text":"扩大考试难度"},{"key":"C","text":"追求学校排名"},{"key":"D","text":"立德树人"}],"answer":"D","explanation":"立德树人是教育的根本任务，教育应培养德智体美劳全面发展的社会主义建设者和接班人。考试、排名等工具不能取代育人根本目标。","knowledgePoints":["教育强国","立德树人"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-054","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"推动中华优秀传统文化创造性转化、创新性发展，正确做法是：","materialId":null,"options":[{"key":"A","text":"对传统文化不加鉴别地全盘复原"},{"key":"B","text":"结合时代条件赋予优秀传统文化新的表达和实践价值"},{"key":"C","text":"把传统文化与现代生活完全隔离"},{"key":"D","text":"仅将传统文化作为商业符号"}],"answer":"B","explanation":"创造性转化、创新性发展要求取其精华、赋予时代内涵，使中华优秀传统文化与当代社会相适应、与现代文明相协调，不是照搬复古或单纯商业化。","knowledgePoints":["中华优秀传统文化","两创"],"sourceRefs":[{"kind":"official","title":"关于实施中华优秀传统文化传承发展工程的意见","url":"https://www.gov.cn/zhengce/2017-01/25/content_5163472.htm","publishedAt":"2017-01-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-055","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"繁荣发展文化事业和文化产业，应当把什么放在首位？","materialId":null,"options":[{"key":"A","text":"社会效益"},{"key":"B","text":"短期流量"},{"key":"C","text":"资本回报"},{"key":"D","text":"市场份额"}],"answer":"A","explanation":"文化建设应坚持以人民为中心，把社会效益放在首位、社会效益和经济效益相统一。市场和资本指标可以考虑，但不能凌驾于正确价值导向和社会效益。","knowledgePoints":["文化事业和文化产业","社会效益"],"sourceRefs":[{"kind":"official","title":"党的二十大报告","url":"https://www.gov.cn/xinwen/2022-10/25/content_5721685.htm","publishedAt":"2022-10-25","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-056","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"推进碳达峰碳中和，正确的工作原则是：","materialId":null,"options":[{"key":"A","text":"全国各地采取完全相同的达峰时间和路径"},{"key":"B","text":"先立后破，通盘谋划，科学考核"},{"key":"C","text":"立即停止一切化石能源使用"},{"key":"D","text":"只依靠限制生产实现减排"}],"answer":"B","explanation":"实现“双碳”目标要立足国情，坚持全国统筹、节约优先、双轮驱动、内外畅通、防范风险，处理好发展与减排关系，先立后破，不能简单化和“一刀切”。","knowledgePoints":["碳达峰碳中和","先立后破"],"sourceRefs":[{"kind":"official","title":"中共中央 国务院关于完整准确全面贯彻新发展理念做好碳达峰碳中和工作的意见","url":"https://www.gov.cn/zhengce/2021-10/24/content_5644613.htm","publishedAt":"2021-10-24","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-057","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"生态环境治理中实行生态保护红线、环境质量底线、资源利用上线和生态环境准入清单，体现的是：","materialId":null,"options":[{"key":"A","text":"以生态环境分区管控优化开发保护格局"},{"key":"B","text":"用单一排污标准替代空间治理"},{"key":"C","text":"取消地方生态环境责任"},{"key":"D","text":"允许突破资源环境承载能力发展"}],"answer":"A","explanation":"“三线一单”通过划定生态环境约束边界和准入要求，实施差异化、精细化的分区管控，使经济社会发展与资源环境承载能力相协调。","knowledgePoints":["生态环境分区管控","三线一单"],"sourceRefs":[{"kind":"official","title":"关于加强生态环境分区管控的意见","publishedAt":"2024-03-17","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-058","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"积极应对人口老龄化，发展养老服务体系应当：","materialId":null,"options":[{"key":"A","text":"只建设大型机构养老"},{"key":"B","text":"推动居家、社区、机构养老协调发展和医养康养结合"},{"key":"C","text":"把养老责任全部交给家庭"},{"key":"D","text":"限制社会力量提供养老服务"}],"answer":"B","explanation":"养老服务需形成居家社区机构相协调、医养康养相结合的供给体系，发挥政府、市场、社会、家庭多方作用，以满足老年人多层次多样化需求。","knowledgePoints":["积极应对人口老龄化","养老服务体系"],"sourceRefs":[{"kind":"official","title":"国家积极应对人口老龄化中长期规划","publishedAt":"2019-11-21","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-059","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"hard","stem":"某资源型城市一方面布局新能源产业，另一方面对传统能源实行安全有序替代，并建立转型就业培训和生态补偿机制。该方案最能体现：","materialId":null,"options":[{"key":"A","text":"降碳、减污、扩绿、增长协同推进"},{"key":"B","text":"生态治理与经济社会发展相互排斥"},{"key":"C","text":"只要发展新能源即可忽视能源安全"},{"key":"D","text":"转型成本应完全由劳动者承担"}],"answer":"A","explanation":"方案同时考虑新能源发展、传统能源安全替代、就业转型和生态补偿，兼顾降碳减污、扩绿增长及民生安全，体现经济社会发展全面绿色转型的系统协同要求。","knowledgePoints":["绿色转型","降碳减污扩绿增长"],"sourceRefs":[{"kind":"official","title":"中共中央 国务院关于加快经济社会发展全面绿色转型的意见","url":"https://www.gov.cn/zhengce/202408/content_6967663.htm","publishedAt":"2024-08-11","accessedAt":"2026-06-18"}],"status":"reviewed"},{"id":"politics-060","category":"政治理论","subtype":"经济社会文化生态建设","difficulty":"medium","stem":"完善公共文化服务体系，最符合以人民为中心导向的举措是：","materialId":null,"options":[{"key":"A","text":"将优质文化资源仅集中在中心城市"},{"key":"B","text":"推进城乡公共文化服务体系一体建设，提高基本公共文化服务可及性"},{"key":"C","text":"以高票价作为公共文化场馆主要门槛"},{"key":"D","text":"用商业演出完全替代基本公共文化服务"}],"answer":"B","explanation":"公共文化服务具有基本性、公益性和均等化要求。城乡一体建设并推动优质资源下沉，有利于保障人民基本文化权益；单纯集中资源或设置高门槛会削弱可及性。","knowledgePoints":["公共文化服务","文化惠民"],"sourceRefs":[{"kind":"official","title":"中华人民共和国公共文化服务保障法","publishedAt":"2016-12-26","accessedAt":"2026-06-18"}],"status":"reviewed"}]};
